import { Controller } from "@hotwired/stimulus"

// Connects to data-controller="popup-window"
export default class extends Controller {
  // Define URL and a new 'name' for the popup as values.
  static values = {
    url: String,
    name: { type: String, default: "formPopup" } // Add name with a default value.
  }

  // Action to open the new window
  open() {
    const width = window.innerWidth * 0.6;
    const height = window.innerHeight * 0.8;
    const left = (window.innerWidth - width) / 2;
    const top = (window.innerHeight - height) / 2;

    window.open(
      this.urlValue,
      this.nameValue, // Use the dynamic name value instead of a hardcoded string.
      `width=${width},height=${height},top=${top},left=${left}`
    );
  }
}

